def predict(board, action):
    row, col = action[1], action[2]
    char_to_change = 'G'
    char_to_replace_with = 'W'

    # Find the cell to change
    for r in range(64):
        for c in range(64):
            if board[r][c] == char_to_change:
                if r == row and c == col:
                    board[r][c] = char_to_replace_with
                elif r > row or (r == row and c > col):
                    board[r][c] = 'W' if board[r][c] == 'G' else 'G'

    # Replace 'p' with 'W' in the 8x8 area around the changed cell
    for r in range(max(0, row-3), min(64, row+4)):
        for c in range(max(0, col-3), min(64, col+4)):
            if board[r][c] == 'p':
                board[r][c] = 'W'

    return board
